def approved_totals(rows, cutoff):
    """
    计算每个项目在截止日期前已批准记录的最大修订号对应的最小金额。

    筛选顺序：
    1. 过滤出 status 为 'approved' 且 revision <= cutoff 的记录。
    2. 按项目分组。
    3. 对于每个项目，找到最大的合格 revision。
    4. 在该最大 revision 的所有记录中，取最小的 amount。
    5. 返回按项目字典序排列的 (project, amount) 列表。
    """
    # 第一步：筛选合格记录并收集每个项目的最大合格 revision
    # 使用字典存储每个项目的最大 revision
    max_rev_dict = {}

    # 遍历所有记录，找出每个项目的最大合格 revision
    for row in rows:
        project, revision, status, amount = row
        # 检查状态是否为 approved 且 revision 不超过 cutoff
        if status == 'approved' and revision <= cutoff:
            # 如果该项目尚未在字典中，或者当前 revision 更大，则更新
            if project not in max_rev_dict:
                max_rev_dict[project] = revision
            else:
                if revision > max_rev_dict[project]:
                    max_rev_dict[project] = revision

    # 第二步：对于每个项目，在最大 revision 的记录中找最小 amount
    # 使用字典存储每个项目最终的最小 amount
    min_amount_dict = {}

    # 遍历所有记录，找出每个项目在最大合格 revision 下的最小 amount
    for row in rows:
        project, revision, status, amount = row
        # 再次检查状态和 cutoff，确保只处理合格记录
        if status == 'approved' and revision <= cutoff:
            # 检查该 revision 是否是该项目的最大合格 revision
            if project in max_rev_dict and revision == max_rev_dict[project]:
                # 如果该项目尚未在 min_amount_dict 中，或者当前 amount 更小，则更新
                if project not in min_amount_dict:
                    min_amount_dict[project] = amount
                else:
                    if amount < min_amount_dict[project]:
                        min_amount_dict[project] = amount

